// Helper to find hexagram by lines (from line 1 to 6)
export function findHexagramByLines(lines: number[]): Hexagram {
  const matched = HEXAGRAMS.find(h => 
    h.lines[0] === lines[0] &&
    h.lines[1] === lines[1] &&
    h.lines[2] === lines[2] &&
    h.lines[3] === lines[3] &&
    h.lines[4] === lines[4] &&
    h.lines[5] === lines[5]
  );
  return matched || HEXAGRAMS[0];
}

// Helper to find hexagram by upper and lower trigram names
export function findHexagramByTrigrams(upper: string, lower: string): Hexagram {
  const matched = HEXAGRAMS.find(h => h.upperTrigram === upper && h.lowerTrigram === lower);
  return matched || HEXAGRAMS[0];
}

// Helper to compute transformed hexagram from primary hexagram and changing lines (1-indexed: 1..6)
export function getTransformedHexagram(primary: Hexagram, changingLines: number[]): Hexagram | undefined {
  if (!changingLines || changingLines.length === 0) {
    return undefined;
  }
  const newLines = [...primary.lines] as [number, number, number, number, number, number];
  changingLines.forEach(lineIdx => {
    const arrIdx = lineIdx - 1;
    if (arrIdx >= 0 && arrIdx < 6) {
      newLines[arrIdx] = newLines[arrIdx] === 1 ? 0 : 1; // Đổi Dương thành Âm, Âm thành Dương
    }
  });
  return findHexagramByLines(newLines);
}
